// Add uploads a single file as multipart/form-data, mirroring
// CallLogsService.AddRecording: pass the file name and a reader for the
// content, and the multipart body is built for you. The encoded body is
// buffered in memory so the request is replayable, which lets the retry
// transport resend uploads after 429/5xx responses (use
// WithFilesRequestOptions(pipedrive.WithNoRetry()) to opt out). Associate
// the upload with deals, persons and other entities via the WithFile*ID
// options.
func (s *FilesService) Add(ctx context.Context, fileName string, content io.Reader, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if fileName == "" {
		return nil, fmt.Errorf("file name is required")
	}
	if content == nil {
		return nil, fmt.Errorf("file content is required")
	}

	contentType, body, err := multipartbody.NewFile("file", fileName, content, cfg.fileFormFields()...)
	if err != nil {
		return nil, err
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

